def dispatch(dom, event):
    sel = event["id"]
    idx = sel.split("-")[1]
    for node in dom["children"]:
        nid = node.get("id", "")
        if nid.startswith("tab-"):
            node["attrs"]["aria-selected"] = "true" if nid == sel else "false"
        elif nid.startswith("panel-"):
            node["attrs"]["hidden"] = (nid != "panel-" + idx)
